const body = $('Webhook POST').first().json.body || {};

// Liste blanche stricte du schema PRD §3.2 - EXACTEMENT ces 11 champs, rien d'autre.
// Un champ supplementaire (uuid, ip, nom, device...) est un rejet, pas un avertissement.
const CHAMPS_AUTORISES = ['ts', 'grp', 'defi_id', 'notion_id', 'palier', 'set_id', 'item_id', 'result', 'ctx', 'rang_local', 'dt_jours'];
const erreurs = [];

const champsEtrangers = Object.keys(body).filter((k) => !CHAMPS_AUTORISES.includes(k));
if (champsEtrangers.length > 0) erreurs.push('champ(s) hors schema : ' + champsEtrangers.length + ' champ(s)');

function estChaineNonVide(v) { return typeof v === 'string' && v.length > 0; }

if (!estChaineNonVide(body.ts) || Number.isNaN(Date.parse(body.ts))) erreurs.push('ts invalide');
if (!estChaineNonVide(body.grp)) erreurs.push('grp invalide');
if (!estChaineNonVide(body.defi_id)) erreurs.push('defi_id invalide');
if (!estChaineNonVide(body.notion_id)) erreurs.push('notion_id invalide');
if (body.palier !== 'nI' && body.palier !== 'nF') erreurs.push('palier invalide');
if (!estChaineNonVide(body.set_id)) erreurs.push('set_id invalide');
if (!estChaineNonVide(body.item_id)) erreurs.push('item_id invalide');
if (body.result !== 0 && body.result !== 1) erreurs.push('result invalide');
if (!['df', 'maison', 'classe'].includes(body.ctx)) erreurs.push('ctx invalide');
if (!Number.isInteger(body.rang_local) || body.rang_local < 1) erreurs.push('rang_local invalide');
if (body.dt_jours !== null && !(typeof body.dt_jours === 'number' && body.dt_jours >= 0)) erreurs.push('dt_jours invalide');

// Jamais un spread de body : les champs sont repris un par un, pour que meme un corps
// deja filtre cote navigateur (T5, livrable A) ne puisse pas faire passer un champ
// etranger ici par accident (defense en profondeur, G3).
return [{
  json: {
    valide: erreurs.length === 0,
    erreurs: erreurs,
    ts: body.ts,
    grp: body.grp,
    defi_id: body.defi_id,
    notion_id: body.notion_id,
    palier: body.palier,
    set_id: body.set_id,
    item_id: body.item_id,
    result: body.result,
    ctx: body.ctx,
    rang_local: body.rang_local,
    dt_jours: body.dt_jours
  }
}];
